import csv, statistics
from collections import defaultdict

cat={}
with open(CATALOG_CSV) as f:
    for row in csv.DictReader(f):
        cat[row['timeseries_id']]=(row['point_uri'].split('#')[-1], row['point_class'])

def load(tid):
    d=defaultdict(list)
    with open(VALUES_CSV) as f:
        for row in csv.DictReader(f):
            if row['timeseries_id']==tid:
                d[row['timestamp'][:7]].append(float(row['value']))
    return d

sensors=[]
with open(CATALOG_CSV) as f:
    for row in csv.DictReader(f):
        if row['point_class']=='Zone_Air_Temperature_Sensor':
            sensors.append((row['point_uri'].split('#')[-1], row['timeseries_id']))
sensors.sort()

for name,tid in sensors:
    d=load(tid)
    months=sorted(m for m in d if len(d[m])>100)
    means={m:sum(v)/len(v) for m,v in d.items()}
    stds={m:statistics.pstdev(v) for m,v in d.items()}
    print(name)
    row=[]
    for m in months:
        row.append(f"{m[:7]}:{means[m]:5.2f}/{stds[m]:.2f}")
    print("  "+" ".join(row))

